mapper.select:
SELECT '期初余额'summary,IFNULL(SUM(bap.period_end_balance),0) balance
from book_auxiliary_period bap
LEFT JOIN book_auxiliary ba ON bap.auxiliary_id = ba.auxiliary_id
where bap.subject_id = #{subjectId} and bap.year_period = #{currentPeriod} and bap.del_flag = '0'

    and ba.auxiliary_type_id = #{auxiliaryTypeId}


    and ba.auxiliary_id = #{auxiliaryId}
